/** Seed routes + places: bundled static JSON, generated by scripts/fetch_routes.py
 *  from live OSRM / Nominatim responses. Seed data is READ-ONLY in the app.
 *  User edits live in the routeOverrides table (db.ts), keyed by route ID. */
import { db } from "./db";
import { haversineKm, roadStraightRatio } from "./calc";

export interface Place {
  id: string;
  name: string;
  aliases: string[];
  category: string;
  lat: number;
  lon: number;
  source: string;
  fetched_at: string;
}

export interface SeedRoute {
  id: string;
  from: string;
  to: string;
  km: number;
  duration_min: number;
  straight_km: number;
  road_straight_ratio: number | null;
  source: string;
  engine: string;
  profile: string;
  fetched_at: string;
  verified_km: number | null;
  verified_source: string | null;
  deviation_pct: number | null;
  flag?: string;
}

export interface ResolvedRoute {
  id: string;
  fromId: string;
  fromName: string;
  toId: string;
  toName: string;
  km: number;
  /** e.g. "Source: OSRM, checked 2026-11-09" | "Manual, edited 2026-11-09" | "User override, edited ..." */
  sourceLabel: string;
  isOverride: boolean;
  isDeleted: boolean;
  straightKm: number | null;
  ratio: number | null;
  ratioFlag: boolean;
}

let placesCache: Place[] | null = null;
let routesCache: SeedRoute[] | null = null;

export async function loadPlaces(): Promise<Place[]> {
  if (placesCache) return placesCache;
  const res = await fetch(`${import.meta.env.BASE_URL}data/places.json`);
  if (!res.ok) throw new Error(`places.json failed: ${res.status}`);
  const seed: Place[] = await res.json();
  const custom = await db.placesCustom.toArray();
  placesCache = [
    ...seed,
    ...custom.map((c) => ({ id: c.id, name: c.name, aliases: c.aliases, category: c.category, lat: 0, lon: 0, source: "Custom place (user)", fetched_at: c.createdAt.slice(0, 10) })),
  ];
  return placesCache;
}

export async function loadSeedRoutes(): Promise<SeedRoute[]> {
  if (routesCache) return routesCache;
  const res = await fetch(`${import.meta.env.BASE_URL}data/routes-seed.json`);
  if (!res.ok) throw new Error(`routes-seed.json failed: ${res.status}`);
  const seed: SeedRoute[] = await res.json();
  routesCache = seed;
  return seed;
}

export function routeId(fromId: string, toId: string): string {
  return `${fromId}--${toId}`;
}

/** Resolve a route: override wins over seed; soft-deleted override hides it.
 *  Returns null when no stored route exists (caller then offers manual km /
 *  live lookup when online). */
export async function resolveRoute(fromId: string, toId: string, places: Place[]): Promise<ResolvedRoute | null> {
  const id = routeId(fromId, toId);
  const from = places.find((p) => p.id === fromId);
  const to = places.find((p) => p.id === toId);
  const fromName = from?.name ?? fromId;
  const toName = to?.name ?? toId;
  const straightKm = from && to && from.lat && to.lat ? Math.round(haversineKm(from.lat, from.lon, to.lat, to.lon) * 100) / 100 : null;

  const ov = await db.routeOverrides.get(id);
  if (ov) {
    const ratio = straightKm ? roadStraightRatio(ov.km, straightKm) : null;
    return {
      id, fromId, fromName, toId, toName, km: ov.km,
      sourceLabel: ov.source, isOverride: true, isDeleted: ov.deleted,
      straightKm, ratio, ratioFlag: ratio !== null && ratio > 2.0,
    };
  }
  const seed = (await loadSeedRoutes()).find((r) => r.id === id);
  if (!seed) return null;
  const ratio = straightKm ? roadStraightRatio(seed.km, straightKm) : seed.road_straight_ratio;
  return {
    id, fromId, fromName, toId, toName, km: seed.km,
    sourceLabel: `Source: ${seed.source}, checked ${seed.fetched_at}`,
    isOverride: false, isDeleted: false,
    straightKm, ratio, ratioFlag: ratio !== null && ratio > 2.0,
  };
}

/** Live lookup when online (OSRM demo server), cached into routeOverrides
 *  and labelled with source + date. Returns null when offline / failed —
 *  the caller must then offer manual km entry, never a guessed value. */
export async function liveLookupKm(from: Place, to: Place): Promise<{ km: number; sourceLabel: string } | null> {
  if (!navigator.onLine) return null;
  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${from.lon},${from.lat};${to.lon},${to.lat}?overview=false`;
    const res = await fetch(url);
    if (!res.ok) return null;
    const d = await res.json();
    if (d.code !== "Ok" || !d.routes?.[0]) return null;
    const km = Math.round((d.routes[0].distance / 1000) * 100) / 100;
    const today = new Date().toISOString().slice(0, 10);
    return { km, sourceLabel: `Source: OSRM live lookup, checked ${today}` };
  } catch {
    return null;
  }
}
